export const SOURCES = ['Website', 'Referral', 'Walk-in', 'Social Media'];

export const STATUS_COLORS = {
  'New Lead':               { bg: '#EFF6FF', text: '#1D4ED8', border: '#BFDBFE' },
  'Contacted':              { bg: '#FFFBEB', text: '#B45309', border: '#FDE68A' },
  'Site Visit Scheduled':   { bg: '#F0FDF4', text: '#15803D', border: '#BBF7D0' },
  'Proposal Sent':          { bg: '#FDF4FF', text: '#7E22CE', border: '#E9D5FF' },
  'Won':                    { bg: '#F0FDF4', text: '#166534', border: '#86EFAC' },
